//! Absence witnesses for monotone removal of constructor quotation memberships.
//! This sidecar neither modifies the portable trace nor supplies general causality.
use crate::causal::{AnalysisLimits, Budget};
use crate::recording::{AtomId, AtomRecord, EventId};
use crate::trace::VerifiedTrace;
use graph_core::{Diagnostic, ErrorKind, Kind, Result, Role};
use std::collections::{BTreeMap, BTreeSet};

pub const SCHEMA: &str = "reflective-visibility-witnesses-v1";
pub const FRAGMENT: &str = "monotone-constructor-unquotation-v1";
pub const LIMITATION: &str = "Necessary constructor-visibility conditions within one checked history, not sufficient admission, complete causality, counterfactual executions or independence. New operative constructor memberships are outside this fragment.";

#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize)]
pub struct Witness {
    pub removed_by: EventId,
    pub used_by: EventId,
    pub atom: AtomId,
    pub membership: AtomId,
}
#[derive(Clone, Debug, serde::Serialize)]
pub struct VisibilityReport {
    pub schema: &'static str,
    pub fragment: &'static str,
    pub limitation: &'static str,
    pub initial_sha256: String,
    pub witnesses: Vec<Witness>,
}

// Independent of matching: derive operative membership by the carrier definition.
fn scan(
    atoms: &BTreeMap<AtomId, AtomRecord>,
    budget: &mut Budget,
) -> Result<(BTreeMap<AtomId, AtomId>, BTreeSet<AtomId>)> {
    budget.work(atoms.len())?;
    budget.retain(atoms.len().saturating_mul(3))?;
    let named: BTreeSet<_> = atoms
        .values()
        .filter(|a| a.kind.role().is_some_and(Role::membership))
        .map(|a| a.fields[1])
        .collect();
    let mut blockers = BTreeMap::new();
    let mut quoted = BTreeSet::new();
    for (id, a) in atoms {
        budget.work(1)?;
        if a.kind.role().is_some_and(Role::membership) && !named.contains(id) {
            let target = a.fields[1];
            quoted.insert(target);
            if matches!(atoms[&target].kind, Kind::Constructor(_)) {
                blockers.insert(*id, target);
            }
        }
    }
    Ok((blockers, quoted))
}

/// Only accepts an already replay-verified trace. Rejects the entire result on
/// fragment escape or resource exhaustion; no partial coverage is silently emitted.
pub fn extract(trace: &VerifiedTrace, limits: AnalysisLimits) -> Result<VisibilityReport> {
    let doc = trace.document();
    let mut budget = Budget::new(limits);
    let size = |a: &AtomRecord| {
        1usize
            .saturating_add(a.fields.len())
            .saturating_add(match &a.kind {
                Kind::Constructor(s) | Kind::Record { label: Some(s), .. } => s.len(),
                _ => 0,
            })
    };
    for a in doc.initial.atoms.values() {
        budget.work(size(a))?;
        budget.retain(size(a))?;
    }
    let mut atoms = doc.initial.atoms.clone();
    let (initial, _) = scan(&atoms, &mut budget)?;
    let mut removed: BTreeMap<AtomId, Vec<(AtomId, EventId)>> = BTreeMap::new();
    let mut witnesses = Vec::new();
    for index in 0..=doc.events.len() {
        let (blockers, quoted) = scan(&atoms, &mut budget)?;
        for (id, target) in &initial {
            budget.work(1)?;
            if atoms.contains_key(id) && blockers.get(id) != Some(target) {
                return Err(Diagnostic::new(
                    ErrorKind::InvalidConfiguration,
                    "visibility fragment excludes quotation of an existing constructor membership",
                ));
            }
        }
        for (id, target) in &blockers {
            budget.work(1)?;
            if initial.get(id) != Some(target) {
                return Err(Diagnostic::new(
                    ErrorKind::InvalidConfiguration,
                    "visibility fragment excludes newly operative constructor memberships",
                ));
            }
        }
        let Some(event) = doc.events.get(index) else {
            break;
        };
        budget.work(atoms.len())?;
        let object_mode = atoms.iter().any(|(id, a)| {
            !quoted.contains(id)
                && a.kind.role() == Some(Role::ModeObject)
                && a.fields[0] == event.redex.source
        });
        if object_mode {
            let mut seen = BTreeSet::new();
            for (_, target) in &event.redex.binding {
                budget.work(1)?;
                budget.retain(1)?;
                if !seen.insert(*target) || !matches!(atoms[target].kind, Kind::Constructor(_)) {
                    continue;
                }
                // Checked object matching establishes absence; never infer admission from it.
                debug_assert!(!quoted.contains(target));
                for (membership, removed_by) in removed.get(target).into_iter().flatten() {
                    budget.work(1)?;
                    budget.retain(4)?;
                    witnesses.push(Witness {
                        removed_by: *removed_by,
                        used_by: event.id,
                        atom: *target,
                        membership: *membership,
                    });
                }
            }
        }
        for id in &event.footprint.consumed {
            budget.work(1)?;
            if let Some(target) = initial.get(id) {
                budget.retain(3)?;
                removed.entry(*target).or_default().push((*id, event.id));
            }
            atoms.remove(id);
        }
        for (id, a) in &event.fresh {
            budget.work(size(a))?;
            budget.retain(size(a))?;
            atoms.insert(*id, a.clone());
        }
    }
    Ok(VisibilityReport {
        schema: SCHEMA,
        fragment: FRAGMENT,
        limitation: LIMITATION,
        initial_sha256: doc.initial_sha256.clone(),
        witnesses,
    })
}

crates/engine/src/conflict.rs:
//! Exact, bounded residual checks over one complete enabled set. No footprint
//! pruning, rematching, scheduler mutation or cross-schedule unfolding is used.
use crate::causal::{AnalysisLimits, Budget};
use crate::recording::{atom_units, AtomId, AtomRecord, RedexId};
use crate::scheduling::candidate_key;
use crate::{Event, Execution, OperationalBinding, PreparedStep};
use graph_core::{AtomKey, Diagnostic, ErrorKind, Graph, Result};
use std::collections::BTreeMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Residual {
    Survives,
    Invalidated(Diagnostic),
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Pair {
    /// Indices into this snapshot's alternatives, never EventIds.
    pub first: usize,
    pub second: usize,
    pub second_after_first: Residual,
    pub first_after_second: Residual,
    /// Present only when both residuals survive. Equality fixes all original
    /// identities and pairs fresh atoms by occurrence and RHS template order.
    pub commutes: Option<bool>,
    pub corresponding_events: Option<bool>,
}
impl Pair {
    pub fn conflicts(&self) -> bool {
        matches!(self.second_after_first, Residual::Invalidated(_))
            || matches!(self.first_after_second, Residual::Invalidated(_))
    }
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct LocalSnapshot {
    pub state: u64,
    pub pre_state: BTreeMap<AtomId, AtomRecord>,
    pub alternatives: Vec<RedexId>,
    pub pairs: Vec<Pair>,
}
impl LocalSnapshot {
    /// Any exhausted enumeration, residual check or comparison aborts the entire
    /// snapshot with ResourceExhaustion. It is not a conflict/independence result.
    pub fn analyse(execution: &Execution, limits: AnalysisLimits) -> Result<Self> {
        let mut budget = Budget::new(limits);
        charge_graph(execution.graph(), &mut budget)?;
        // Charge before retaining each complete candidate. A single candidate's
        // construction still uses the independent ExecutionLimits. No partial
        // enabled set is published if the retention callback exhausts analysis.
        let mut steps = execution
            .search()
            .enabled_retaining(|step| {
                charge_graph(execution.graph(), &mut budget)?;
                for atom in step.ground_rule().left().values() {
                    let n = atom_units(atom)?;
                    budget.work(n)?;
                    budget.retain(n)?;
                }
                for atom in step.ground_rule().fresh().values() {
                    let n = atom_units(atom)?;
                    budget.work(n)?;
                    budget.retain(n)?;
                    budget.retain(n)?;
                }
                let e = step.event();
                for set in [
                    &e.consumed,
                    &e.preserved,
                    &e.produced,
                    &e.read,
                    &e.entered,
                    &e.exited,
                    &e.altered,
                ] {
                    budget.work(set.len())?;
                    budget.retain(set.len())?;
                }
                Ok(())
            })?
            .into_steps();
        steps.sort_by_cached_key(candidate_key);
        for step in &steps {
            budget.work(1)?;
            budget.retain(4)?;
            for _ in step.binding().assignments() {
                budget.work(1)?;
                budget.retain(2)?;
            }
        }
        let alternatives = steps
            .iter()
            .map(|s| RedexId::new(execution.committed_steps(), s.binding(), s.event()))
            .collect();
        let mut pairs = Vec::new();
        for first in 0..steps.len() {
            for second in first + 1..steps.len() {
                budget.work(1)?;
                budget.retain(10)?;
                let a = ordered(execution, &steps[first], &steps[second], &mut budget)?;
                let b = ordered(execution, &steps[second], &steps[first], &mut budget)?;
                let (commutes, corresponding_events) = match (&a, &b) {
                    (Branch::Complete(ga, ea, eb), Branch::Complete(gb, fb, fa)) => {
                        let mut mapping = BTreeMap::new();
                        for (key, _) in execution.graph().iter() {
                            budget.work(1)?;
                            budget.retain(2)?;
                            mapping.insert(key, key);
                        }
                        for (left, right) in [(ea, fa), (eb, fb)] {
                            if left.produced.len() != right.produced.len() {
                                return Err(Diagnostic::new(
                                    ErrorKind::InvalidConfiguration,
                                    "same residual changed RHS fresh cardinality",
                                ));
                            }
                            for (&x, &y) in left.produced.iter().zip(&right.produced) {
                                budget.work(1)?;
                                budget.retain(2)?;
                                mapping.insert(x, y);
                            }
                        }
                        (
                            Some(equal_graphs(ga, gb, &mapping, &mut budget)?),
                            Some(
                                equal_events(ea, fa, &mapping, &mut budget)?
                                    && equal_events(eb, fb, &mapping, &mut budget)?,
                            ),
                        )
                    }
                    _ => (None, None),
                };
                pairs.push(Pair {
                    first,
                    second,
                    second_after_first: a.status(),
                    first_after_second: b.status(),
                    commutes,
                    corresponding_events,
                });
            }
        }
        Ok(Self {
            state: execution.committed_steps(),
            pre_state: execution
                .graph()
                .iter()
                .map(|(k, a)| (k.into(), a.into()))
                .collect(),
            alternatives,
            pairs,
        })
    }
}
enum Branch {
    Complete(Graph, Event, Event),
    Invalid(Diagnostic),
}
impl Branch {
    fn status(&self) -> Residual {
        match self {
            Self::Complete(..) => Residual::Survives,
            Self::Invalid(d) => Residual::Invalidated(d.clone()),
        }
    }
}
fn charge_graph(graph: &Graph, budget: &mut Budget) -> Result<()> {
    budget.work(1)?;
    for (_, a) in graph.iter() {
        let n = atom_units(a)?;
        budget.work(n)?;
        budget.retain(n)?;
    }
    Ok(())
}
fn ordered(
    original: &Execution,
    first: &PreparedStep,
    second: &PreparedStep,
    budget: &mut Budget,
) -> Result<Branch> {
    charge_graph(original.graph(), budget)?;
    let mut hypothetical = Execution::new(original.graph().clone(), original.limits())?;
    budget.work(1)?;
    let a = hypothetical.prepare(first.binding().clone())?;
    let ea = hypothetical.commit(a)?;
    charge_graph(hypothetical.graph(), budget)?;
    let source = hypothetical
        .view()?
        .rule(second.binding().source())
        .map(|r| (r.revision, r.active));
    // Revision identity is part of an occurrence even if a different live rule
    // could happen to accept the same old binding after the first transaction.
    if source.is_none_or(|(revision, active)| revision != second.event().source_revision || !active)
    {
        return Ok(Branch::Invalid(Diagnostic::new(
            ErrorKind::StaleCandidate,
            "residual source revision or activation changed",
        )));
    }
    budget.work(1)?;
    let b = match hypothetical.prepare(OperationalBinding::new(
        second.binding().source(),
        second.binding().assignments().clone(),
    )) {
        Ok(b) => b,
        Err(d) if d.kind() == ErrorKind::ResourceExhaustion => return Err(d),
        Err(d) => return Ok(Branch::Invalid(d)),
    };
    let eb = hypothetical.commit(b)?;
    charge_graph(hypothetical.graph(), budget)?;
    Ok(Branch::Complete(hypothetical.graph().clone(), ea, eb))
}
fn equal_graphs(
    a: &Graph,
    b: &Graph,
    map: &BTreeMap<AtomKey, AtomKey>,
    budget: &mut Budget,
) -> Result<bool> {
    if a.len() != b.len() {
        return Ok(false);
    }
    // The per-occurrence fresh ranges are disjoint, hence this mapping is
    // injective on the resulting graph. Check surjectivity via equal cardinality.
    for (key, atom) in a.iter() {
        budget.work(atom_units(atom)?)?;
        let Some(target) = map.get(&key).and_then(|k| b.get(*k)) else {
            return Ok(false);
        };
        if atom.kind != target.kind
            || atom.fields.len() != target.fields.len()
            || atom
                .fields
                .iter()
                .zip(&target.fields)
                .any(|(x, y)| map.get(x) != Some(y))
        {
            return Ok(false);
        }
    }
    Ok(true)
}
fn equal_events(
    a: &Event,
    b: &Event,
    map: &BTreeMap<AtomKey, AtomKey>,
    budget: &mut Budget,
) -> Result<bool> {
    budget.work(2)?;
    if map.get(&a.source) != Some(&b.source)
        || map.get(&a.source_revision) != Some(&b.source_revision)
    {
        return Ok(false);
    }
    for (x, y) in [
        (&a.consumed, &b.consumed),
        (&a.preserved, &b.preserved),
        (&a.produced, &b.produced),
        (&a.read, &b.read),
        (&a.entered, &b.entered),
        (&a.exited, &b.exited),
        (&a.altered, &b.altered),
    ] {
        if x.len() != y.len() {
            return Ok(false);
        }
        for key in x {
            budget.work(1)?;
            if !map.get(key).is_some_and(|k| y.contains(k)) {
                return Ok(false);
            }
        }
    }
    Ok(true)
}

crates/engine/src/counterfactual.rs:
//! Exact-occurrence, order-preserving deletion interventions on verified traces.
//! This is a bounded experimental explanation, not an unfolding or actual-cause logic.
use crate::causal::{AnalysisLimits, Budget};
use crate::recording::{AtomId, EventId, RecordedEvent};
use crate::trace::VerifiedTrace;
use crate::{Execution, OperationalBinding, PreparedStep};
use graph_core::{AtomKey, Diagnostic, ErrorKind, LimitKind, Result};
use std::collections::{BTreeMap, BTreeSet};

pub const SCHEMA: &str = "reflective-occurrence-interventions-v1";
pub const LIMITATION: &str = "Complete only for order-preserving subsets of this recorded prefix. Prefix events keep exact source revisions, transported bindings and checked effects. The target query explicitly chooses exact occurrence or existential source-revision admission. Not arbitrary schedules, prefix rematching, structural-model actual causality, independence or cache-invalidation evidence. Minimal supports are not an upward-closed enabling formula.";

#[derive(Clone, Copy, Debug, PartialEq, Eq, serde::Serialize)]
pub enum Query {
    ExactOccurrence,
    /// Existential matching is allowed only for the target, never prefix events.
    SourceRevision,
}

#[derive(Clone, Copy, Debug)]
pub struct Limits {
    /// Explicit exponential bound; values greater than 12 are unsupported.
    pub max_prefix: usize,
    /// Bookkeeping work/storage only. Each native preparation separately uses
    /// the verified trace's execution bounds; these are not wall-clock limits.
    pub analysis: AnalysisLimits,
}
impl Default for Limits {
    fn default() -> Self {
        Self {
            max_prefix: 8,
            analysis: AnalysisLimits::default(),
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize)]
#[serde(tag = "kind")]
pub enum Outcome {
    Admitted,
    TargetUnavailable { reason: String },
    TargetRejected { reason: String },
    InfeasiblePrefix { at: EventId, reason: String },
}
#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize)]
pub struct Trial {
    pub retained: Vec<EventId>,
    pub outcome: Outcome,
    /// One admitted target binding, expressed in ORIGINAL trace identities.
    pub witness_binding: Option<Vec<(AtomId, AtomId)>>,
}
#[derive(Clone, Debug, serde::Serialize)]
pub struct Report {
    pub schema: &'static str,
    pub limitation: &'static str,
    pub initial_sha256: String,
    pub target: EventId,
    pub query: Query,
    pub trials: Vec<Trial>,
    /// Alternative exact successful selections, not sufficient in all supersets.
    pub minimal_supports: Vec<Vec<EventId>>,
    pub necessary_in_this_universe: Vec<EventId>,
    pub native_queries: usize,
}

enum Attempt {
    Ready(Box<PreparedStep>),
    Unavailable(String),
    Rejected(String),
}

fn prepare(
    run: &Execution,
    event: &RecordedEvent,
    names: &BTreeMap<AtomId, AtomKey>,
    budget: &mut Budget,
    calls: &mut usize,
) -> Result<Attempt> {
    budget.work(event.redex.binding.len().saturating_add(1))?;
    let live = |id: &AtomId| {
        names
            .get(id)
            .copied()
            .filter(|k| run.graph().get(*k).is_some())
    };
    let Some(source) = live(&event.redex.source) else {
        return Ok(Attempt::Unavailable("recorded source is absent".into()));
    };
    let Some(rule) = run.configuration().rules.get(&source) else {
        return Ok(Attempt::Unavailable(
            "recorded source is not a live rule".into(),
        ));
    };
    if live(&event.redex.revision) != Some(rule.revision) {
        return Ok(Attempt::Unavailable(
            "exact source revision is absent or replaced".into(),
        ));
    }
    let mut binding = BTreeMap::new();
    for (a, b) in &event.redex.binding {
        let (Some(a), Some(b)) = (live(a), live(b)) else {
            return Ok(Attempt::Unavailable(
                "recorded binding identity is absent".into(),
            ));
        };
        budget.retain(2)?;
        binding.insert(a, b);
    }
    *calls += 1;
    match run.prepare(OperationalBinding::new(source, binding)) {
        Ok(step) => Ok(Attempt::Ready(Box::new(step))),
        Err(e) if e.kind() == ErrorKind::ResourceExhaustion => Err(e),
        Err(e) => Ok(Attempt::Rejected(e.to_string())),
    }
}

// Fresh allocation is ordered by RHS template identity. Omitting unrelated
// producers can shift numeric IDs; pair by allocation order, then CHECK the
// complete resulting fresh records and ground effect. Never guess by labels.
fn extend_names(
    event: &RecordedEvent,
    step: &PreparedStep,
    names: &mut BTreeMap<AtomId, AtomKey>,
    budget: &mut Budget,
) -> Result<()> {
    let unsupported = || {
        Diagnostic::new(
            ErrorKind::InvalidConfiguration,
            "unsupported intervention: recorded ground effect does not transport exactly",
        )
    };
    if event.fresh.len() != step.ground_rule().fresh().len() {
        return Err(unsupported());
    }
    for (old, new) in event.fresh.keys().zip(step.ground_rule().fresh().keys()) {
        budget.work(1)?;
        budget.retain(2)?;
        if names.insert(*old, *new).is_some() {
            return Err(unsupported());
        }
    }
    for (old, atom) in &event.fresh {
        budget.work(1 + atom.fields.len())?;
        let fresh = &step.ground_rule().fresh()[&names[old]];
        if atom.kind != fresh.kind
            || atom
                .fields
                .iter()
                .map(|id| names.get(id).copied())
                .collect::<Option<Vec<_>>>()
                .as_ref()
                != Some(&fresh.fields)
        {
            return Err(unsupported());
        }
    }
    for (old, new) in [
        (&event.footprint.consumed, &step.event().consumed),
        (&event.footprint.preserved, &step.event().preserved),
    ] {
        budget.work(old.len())?;
        budget.retain(old.len())?;
        if old
            .iter()
            .map(|id| names.get(id).copied())
            .collect::<Option<BTreeSet<_>>>()
            .as_ref()
            != Some(new)
        {
            return Err(unsupported());
        }
    }
    Ok(())
}

/// Enumerate the entire selected finite universe, or return an error without a
/// partial report. Original trace/graph and allocator are never mutated.
pub fn analyse(trace: &VerifiedTrace, target: EventId, limits: Limits) -> Result<Report> {
    analyse_query(trace, target, Query::ExactOccurrence, limits)
}

pub fn analyse_query(
    trace: &VerifiedTrace,
    target: EventId,
    query: Query,
    limits: Limits,
) -> Result<Report> {
    let doc = trace.document();
    let n = usize::try_from(target.0).map_err(|_| {
        Diagnostic::new(ErrorKind::InvalidConfiguration, "target event out of range")
    })?;
    if n >= doc.events.len() {
        return Err(Diagnostic::new(
            ErrorKind::InvalidConfiguration,
            "target event out of range",
        ));
    }
    if n > limits.max_prefix || limits.max_prefix > 12 {
        return Err(Diagnostic::exhausted(
            LimitKind::AnalysisWork,
            "occurrence intervention prefix bound exceeded (hard maximum 12)",
        ));
    }
    let mut budget = Budget::new(limits.analysis);
    let mut trials = Vec::new();
    let mut successful = Vec::new();
    let mut calls = 0;
    let native = doc.settings.execution()?;
    for mask in 0..(1usize << n) {
        let initial_units = doc.initial.atoms.values().try_fold(0usize, |sum, atom| {
            let label = match &atom.kind {
                graph_core::Kind::Constructor(s)
                | graph_core::Kind::Record { label: Some(s), .. } => s.len(),
                _ => 0,
            };
            sum.checked_add(
                1usize
                    .saturating_add(atom.fields.len())
                    .saturating_add(label),
            )
            .ok_or_else(|| {
                Diagnostic::exhausted(LimitKind::AnalysisStorage, "initial graph size overflow")
            })
        })?;
        budget.work(initial_units.saturating_add(n + 1))?;
        budget.retain(initial_units)?;
        budget.retain(
            doc.initial
                .atoms
                .len()
                .saturating_mul(3)
                .saturating_add(n + 2),
        )?;
        let graph = doc.initial.restore(&native.graph)?;
        let mut names: BTreeMap<_, _> = graph.iter().map(|(k, _)| (AtomId::from(k), k)).collect();
        let mut run = Execution::new(graph, native)?;
        let retained: Vec<_> = (0..n)
            .filter(|i| mask & (1 << i) != 0)
            .map(|i| EventId(i as u64))
            .collect();
        let mut outcome = None;
        for id in &retained {
            let event = &doc.events[id.0 as usize];
            match prepare(&run, event, &names, &mut budget, &mut calls)? {
                Attempt::Ready(step) => {
                    extend_names(event, &step, &mut names, &mut budget)?;
                    run.commit(*step)?;
                }
                Attempt::Unavailable(reason) | Attempt::Rejected(reason) => {
                    outcome = Some(Outcome::InfeasiblePrefix { at: *id, reason });
                    break;
                }
            }
        }
        let mut witness_binding = None;
        let outcome = match outcome {
            Some(outcome) => outcome,
            None => {
                match target_attempt(&run, &doc.events[n], &names, query, &mut budget, &mut calls)?
                {
                    Attempt::Ready(step) => {
                        if query == Query::ExactOccurrence {
                            extend_names(&doc.events[n], &step, &mut names, &mut budget)?;
                        }
                        budget.work(names.len() + step.binding().assignments().len())?;
                        budget.retain(
                            names.len().saturating_mul(2)
                                + step.binding().assignments().len().saturating_mul(2),
                        )?;
                        let inverse: BTreeMap<_, _> = names.iter().map(|(a, b)| (*b, *a)).collect();
                        witness_binding = Some(
                            step.binding()
                                .assignments()
                                .iter()
                                .map(|(a, b)| (inverse[a], inverse[b]))
                                .collect(),
                        );
                        successful.push(mask);
                        Outcome::Admitted
                    }
                    Attempt::Unavailable(reason) => Outcome::TargetUnavailable { reason },
                    Attempt::Rejected(reason) => Outcome::TargetRejected { reason },
                }
            }
        };
        let reason_bytes = match &outcome {
            Outcome::Admitted => 0,
            Outcome::TargetUnavailable { reason }
            | Outcome::TargetRejected { reason }
            | Outcome::InfeasiblePrefix { reason, .. } => reason.len(),
        };
        budget.retain(reason_bytes)?;
        trials.push(Trial {
            retained,
            outcome,
            witness_binding,
        });
    }
    if successful.last() != Some(&((1usize << n) - 1)) {
        return Err(Diagnostic::new(
            ErrorKind::InvalidConfiguration,
            "full recorded prefix failed intervention replay",
        ));
    }
    let mut minimal_supports = Vec::new();
    for &mask in &successful {
        let mut minimal = true;
        for &other in &successful {
            budget.work(1)?;
            if other != mask && other & mask == other {
                minimal = false;
                break;
            }
        }
        if minimal {
            budget.retain(n + 1)?;
            minimal_supports.push(trials[mask].retained.clone());
        }
    }
    let common = successful
        .iter()
        .fold((1usize << n) - 1, |acc, mask| acc & mask);
    budget.retain(n)?;
    Ok(Report {
        schema: SCHEMA,
        limitation: LIMITATION,
        initial_sha256: doc.initial_sha256.clone(),
        target,
        query,
        trials,
        minimal_supports,
        necessary_in_this_universe: (0..n)
            .filter(|i| common & (1 << i) != 0)
            .map(|i| EventId(i as u64))
            .collect(),
        native_queries: calls,
    })
}

fn target_attempt(
    run: &Execution,
    event: &RecordedEvent,
    names: &BTreeMap<AtomId, AtomKey>,
    query: Query,
    budget: &mut Budget,
    calls: &mut usize,
) -> Result<Attempt> {
    if query == Query::ExactOccurrence {
        return prepare(run, event, names, budget, calls);
    }
    budget.work(1)?;
    let Some(source) = names.get(&event.redex.source).copied() else {
        return Ok(Attempt::Unavailable("recorded source is absent".into()));
    };
    let Some(rule) = run.configuration().rules.get(&source) else {
        return Ok(Attempt::Unavailable(
            "recorded source is not a live rule".into(),
        ));
    };
    if names.get(&event.redex.revision).copied() != Some(rule.revision) {
        return Ok(Attempt::Unavailable(
            "exact source revision is absent or replaced".into(),
        ));
    }
    *calls += 1;
    let enabled = run.enabled_for(source)?;
    Ok(match enabled.into_steps().into_iter().next() {
        Some(step) => Attempt::Ready(Box::new(step)),
        None => Attempt::Rejected("no admitted binding for this source revision".into()),
    })
}

crates/engine/src/indexed.rs:
//! Query-local indexed matching and compact enabled-set retention. The direct
//! experimental v1 API is retained; Runner/replay use the separately reserved
//! v2 work contract. Both use complete checked post-state admission.
use crate::scheduling::Scheduler;
use crate::{AdmissionFailure, Execution, OperationalBinding, PreparedStep, RejectedBinding};
use graph_core::{AtomKey, Binding, Graph, Kind, Result, Role, RuleView, Sort};
use std::collections::{BTreeMap, BTreeSet};

pub const PROFILE: &str = "indexed-compact-v1";
type KindKey = (Sort, Option<Role>, Option<String>, usize);
#[derive(Default)]
struct Index {
    sorts: BTreeMap<Sort, Vec<AtomKey>>,
    kinds: BTreeMap<KindKey, Vec<AtomKey>>,
    incoming: BTreeMap<(AtomKey, usize), Vec<AtomKey>>,
}
fn kind_key(kind: &Kind, arity: usize) -> KindKey {
    let label = match kind {
        Kind::Constructor(s) | Kind::Record { label: Some(s), .. } => Some(s.clone()),
        _ => None,
    };
    (kind.sort(), kind.role(), label, arity)
}
impl Index {
    fn build(graph: &Graph, search: &mut crate::CandidateSearch<'_>) -> Result<Self> {
        let mut index = Self::default();
        for (id, atom) in graph.iter() {
            search.charge_work(1 + atom.fields.len())?;
            index.sorts.entry(atom.kind.sort()).or_default().push(id);
            index
                .kinds
                .entry(kind_key(&atom.kind, atom.fields.len()))
                .or_default()
                .push(id);
            for (slot, target) in atom.fields.iter().enumerate() {
                index.incoming.entry((*target, slot)).or_default().push(id);
            }
        }
        Ok(index)
    }
}

/// A complete admission result borrowing its immutable baseline. No graph copies
/// survive enumeration. The borrow disallows mutation/reload while it exists.
#[derive(Debug)]
pub struct CompactEnabled<'a> {
    execution: &'a Execution,
    bindings: Vec<OperationalBinding>,
    rejected: Vec<RejectedBinding>,
    work: usize,
}
impl CompactEnabled<'_> {
    pub(crate) fn into_parts(self) -> (Vec<OperationalBinding>, Vec<RejectedBinding>) {
        (self.bindings, self.rejected)
    }
    pub fn bindings(&self) -> &[OperationalBinding] {
        &self.bindings
    }
    pub fn rejected(&self) -> &[RejectedBinding] {
        &self.rejected
    }
    pub fn work_used(&self) -> usize {
        self.work
    }
    /// Reprepare the selected binding on the unchanged baseline. The caller
    /// publishes the returned scheduler only after a successful checked commit.
    /// Custom schedulers inspecting full candidates are intentionally unsupported.
    pub fn select(self, scheduler: &Scheduler) -> Result<Option<(PreparedStep, Scheduler)>> {
        let mut next = scheduler.clone();
        match next.select_count(self.bindings.len()) {
            None => Ok(None),
            Some(i) => Ok(Some((
                self.execution.prepare(self.bindings[i].clone())?,
                next,
            ))),
        }
    }
}

impl Execution {
    /// Complete raw matching under the indexed-v1 work accounting profile.
    pub fn bindings_indexed(&self, source: AtomKey) -> Result<Vec<OperationalBinding>> {
        let mut search = self.search();
        let view = self.view()?;
        let rule = crate::matching::source_rule(view.configuration(), source)?;
        let hidden = crate::matching::hidden(view.configuration(), &mut search)?;
        let index = Index::build(self.graph(), &mut search)?;
        let mut out = Vec::new();
        enumerate(self.graph(), rule, &hidden, &index, &mut search, |s, b| {
            s.reserve_candidate(b.assignments().len())?;
            out.push(b);
            Ok(())
        })?;
        Ok(out)
    }
    /// Full enabled set, not first-match selection. Each candidate is fully
    /// prepared then discarded; only its binding and rejection evidence remain.
    pub fn enabled_compact(&self) -> Result<CompactEnabled<'_>> {
        self.compact_query(None, false)
    }
    /// Reserve re-materialisation work for every admitted binding, including
    /// custom strategies requiring full candidates. This is profile v2 only.
    pub(crate) fn compact_query(
        &self,
        requested: Option<AtomKey>,
        reserve: bool,
    ) -> Result<CompactEnabled<'_>> {
        let mut search = self.search();
        let view = self.view()?;
        let hidden = crate::matching::hidden(view.configuration(), &mut search)?;
        let index = Index::build(self.graph(), &mut search)?;
        let mut bindings = Vec::new();
        let mut rejected = Vec::new();
        for rule in view.live_rules() {
            if requested.is_some_and(|head| head != rule.head) {
                continue;
            }
            search.charge_work(1)?;
            enumerate(self.graph(), rule, &hidden, &index, &mut search, |s, b| {
                match s.prepare_classified(b.clone()) {
                    Ok(step) => {
                        s.charge_work(step.ground_rule().fresh().len())?;
                        if reserve {
                            s.charge_work(1 + b.assignments().len())?;
                        }
                        bindings.push(b);
                    }
                    Err(AdmissionFailure::Rejected(diagnostic)) => rejected.push(RejectedBinding {
                        binding: b,
                        diagnostic,
                    }),
                    Err(AdmissionFailure::Failed(error)) => return Err(error),
                }
                Ok(())
            })?;
        }
        bindings.sort_by(|a, b| (a.source(), a.assignments()).cmp(&(b.source(), b.assignments())));
        Ok(CompactEnabled {
            execution: self,
            bindings,
            rejected,
            work: search.work_used(),
        })
    }
}

fn enumerate(
    graph: &Graph,
    rule: &RuleView,
    hidden: &BTreeSet<AtomKey>,
    index: &Index,
    search: &mut crate::CandidateSearch<'_>,
    mut visit: impl FnMut(&mut crate::CandidateSearch<'_>, OperationalBinding) -> Result<()>,
) -> Result<()> {
    if !rule.active {
        return Ok(());
    }
    let mut assignment = BTreeMap::new();
    let mut used = BTreeSet::new();
    let mut domains = Vec::new();
    for id in &rule.lhs {
        search.charge_work(1)?;
        let pattern = graph.atom(*id)?;
        if matches!(
            pattern.kind,
            Kind::PatternVariable {
                binding: Binding::AppliedRule,
                ..
            }
        ) {
            if !used.insert(rule.head) {
                return Ok(());
            }
            assignment.insert(*id, rule.head);
            continue;
        }
        let candidates: Vec<_> = match &pattern.kind {
            Kind::PatternVariable { admits, .. } => admits
                .iter()
                .flat_map(|s| index.sorts.get(s).into_iter().flatten())
                .copied()
                .collect(),
            kind => index
                .kinds
                .get(&kind_key(kind, pattern.fields.len()))
                .cloned()
                .unwrap_or_default(),
        };
        search.charge_work(candidates.len())?;
        let mut candidates: Vec<_> = candidates
            .into_iter()
            .filter(|id| rule.meta || !hidden.contains(id))
            .collect();
        candidates.sort();
        if candidates.is_empty() {
            return Ok(());
        }
        domains.push((*id, candidates));
    }
    domains.sort_by_key(|(id, candidates)| (candidates.len(), *id));
    // Iterative DFS; each frame's restricted domain is rebuilt when its parent
    // changes. Incidence is a necessary condition, never an admission shortcut.
    let mut frames: Vec<(Vec<AtomKey>, usize)> = Vec::new();
    let mut depth = 0;
    loop {
        if depth == domains.len() {
            if crate::matching::feasible(graph, &assignment, search)? {
                visit(
                    search,
                    OperationalBinding::new(rule.head, assignment.clone()),
                )?;
            }
            if depth == 0 {
                return Ok(());
            }
            depth -= 1;
            continue;
        }
        let (pattern_id, base) = &domains[depth];
        if let Some(previous) = assignment.remove(pattern_id) {
            used.remove(&previous);
        }
        if frames.len() == depth {
            let mut restricted: Option<Vec<AtomKey>> = None;
            let pattern = graph.atom(*pattern_id)?;
            for (slot, field) in pattern.fields.iter().enumerate() {
                if let Some(target) = assignment.get(field) {
                    let values = index
                        .incoming
                        .get(&(*target, slot))
                        .cloned()
                        .unwrap_or_default();
                    search.charge_work(values.len() + 1)?;
                    if restricted
                        .as_ref()
                        .is_none_or(|old| values.len() < old.len())
                    {
                        restricted = Some(values);
                    }
                }
            }
            for (other, target) in &assignment {
                for (slot, field) in graph.atom(*other)?.fields.iter().enumerate() {
                    search.charge_work(1)?;
                    if field == pattern_id {
                        restricted = Some(vec![graph.atom(*target)?.fields[slot]]);
                    }
                }
            }
            let values = match restricted {
                Some(values) => values
                    .into_iter()
                    .filter(|id| base.binary_search(id).is_ok())
                    .collect(),
                None => {
                    search.charge_work(base.len())?;
                    base.clone()
                }
            };
            frames.push((values, 0));
        }
        let (values, next) = &mut frames[depth];
        let mut advanced = false;
        while *next < values.len() {
            search.charge_work(1)?;
            let target = values[*next];
            *next += 1;
            if !used.insert(target) {
                continue;
            }
            assignment.insert(*pattern_id, target);
            if crate::matching::feasible(graph, &assignment, search)? {
                depth += 1;
                advanced = true;
                break;
            }
            assignment.remove(pattern_id);
            used.remove(&target);
        }
        if !advanced {
            frames.pop();
            if depth == 0 {
                return Ok(());
            }
            depth -= 1;
        }
    }
}

