//! Bounded complete matching, applicability and checked atomic graph transactions.
//! Reproducible scheduling and bounded observation are layered above admission.
pub mod causal;
mod checked;
pub mod conditions;
pub mod conflict;
pub mod counterfactual;
pub mod indexed;
mod matching;
pub mod meta_activity;
pub mod observation;
mod one_shot;
pub mod recording;
pub mod runner;
pub mod scheduling;
mod screened;
pub mod stability;
pub mod trace;
pub mod workflow;
pub use checked::{
    CandidateSearch, Execution, ExecutionLimits, GroundMatch, GroundRule, OperationalBinding,
    PreparedStep, SearchLimits,
};
use graph_core::{
    ensure, validate_with_limits, AtomKey, Binding, Configuration, Diagnostic, ErrorKind, Graph,
    GraphLimits, Kind, NewAtom, Result, Role, Target,
};
pub use matching::{EnabledSet, RejectedBinding};
use std::collections::{BTreeMap, BTreeSet};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Event {
    pub source: AtomKey,
    pub source_revision: AtomKey,
    pub consumed: BTreeSet<AtomKey>,
    pub preserved: BTreeSet<AtomKey>,
    pub produced: BTreeSet<AtomKey>,
    pub read: BTreeSet<AtomKey>,
    pub entered: BTreeSet<AtomKey>,
    pub exited: BTreeSet<AtomKey>,
    pub altered: BTreeSet<AtomKey>,
}

/// Apply only after checking matching, dangling, post-state validity, lifecycle and GC.
/// Any error leaves `graph`, including its identity allocator, unchanged.
pub fn apply_with_binding(
    graph: &mut Graph,
    source: AtomKey,
    binding: &BTreeMap<AtomKey, AtomKey>,
) -> Result<Event> {
    apply_with_binding_with_limits(graph, source, binding, &GraphLimits::default())
}

/// Reference path with explicit resource bounds. Construction edits between calls
/// are not guarded events and cannot silently extend a closed execution history.
pub fn apply_with_binding_with_limits(
    graph: &mut Graph,
    source: AtomKey,
    binding: &BTreeMap<AtomKey, AtomKey>,
    limits: &GraphLimits,
) -> Result<Event> {
    apply_candidate(graph, source, binding, limits).map_err(AdmissionFailure::diagnostic)
}

/// Only explicitly identified applicability predicates may become rejected matches.
/// All other errors abort general enumeration; resource errors are never rejection.
pub(crate) enum AdmissionFailure {
    Rejected(Diagnostic),
    Failed(Diagnostic),
}
impl AdmissionFailure {
    fn rejected(error: Diagnostic, expected: ErrorKind) -> Self {
        if error.kind() != expected || error.kind() == ErrorKind::ResourceExhaustion {
            Self::Failed(error)
        } else {
            Self::Rejected(error)
        }
    }
    pub(crate) fn diagnostic(self) -> Diagnostic {
        match self {
            Self::Rejected(e) | Self::Failed(e) => e,
        }
    }
}
impl From<Diagnostic> for AdmissionFailure {
    fn from(error: Diagnostic) -> Self {
        Self::Failed(error)
    }
}

pub(crate) fn apply_candidate(
    graph: &mut Graph,
    source: AtomKey,
    binding: &BTreeMap<AtomKey, AtomKey>,
    limits: &GraphLimits,
) -> std::result::Result<Event, AdmissionFailure> {
    let before = validate_with_limits(graph, limits)?;
    let (candidate, event, _) =
        prepare_from_validated(graph, source, binding, limits, &before, false)?;
    *graph = candidate;
    Ok(event)
}

/// Internal only: `before` must be the full validator's result for this exact
/// immutable carrier and limits. Execution owns that invariant; callers cannot
/// supply a detached/edited configuration through the public admission API.
pub(crate) fn prepare_from_validated(
    graph: &Graph,
    source: AtomKey,
    binding: &BTreeMap<AtomKey, AtomKey>,
    limits: &GraphLimits,
    before: &Configuration,
    framed: bool,
) -> std::result::Result<(Graph, Event, Configuration), AdmissionFailure> {
    let rule = before.rules.get(&source).ok_or_else(|| {
        Diagnostic::new(ErrorKind::InvalidBinding, "source is not live").at_atom(source)
    })?;
    let binding_error = |e: Diagnostic| e.with_kind(ErrorKind::InvalidBinding).at_atom(source);
    ensure(rule.active, "source is inactive").map_err(binding_error)?;
    ensure(
        binding.keys().eq(rule.lhs.iter()),
        "binding must cover exactly the LHS",
    )
    .map_err(binding_error)?;
    let image: BTreeSet<_> = binding.values().copied().collect();
    ensure(image.len() == binding.len(), "non-injective binding").map_err(binding_error)?;
    let hidden: BTreeSet<_> = before
        .rules
        .values()
        .flat_map(|r| r.representation.iter().copied())
        .collect();
    for (pattern, target) in binding {
        let p = graph.atom(*pattern).map_err(binding_error)?;
        let t = graph.atom(*target).map_err(binding_error)?;
        let at_binding = |e: Diagnostic| {
            binding_error(e)
                .at_atom(*pattern)
                .at_atom(*target)
                .at_role(p.kind.role().or(t.kind.role()))
        };
        ensure(
            rule.meta || !hidden.contains(target),
            "object match enters rule representation",
        )
        .map_err(at_binding)?;
        match &p.kind {
            Kind::PatternVariable { admits, binding } => {
                ensure(admits.contains(&t.kind.sort()), "variable sort mismatch")
                    .map_err(at_binding)?;
                ensure(
                    *binding != Binding::AppliedRule || *target == source,
                    "AppliedRule mismatch",
                )
                .map_err(at_binding)?;
            }
            _ => {
                ensure(
                    p.kind == t.kind && p.fields.len() == t.fields.len(),
                    "concrete atom mismatch",
                )
                .map_err(at_binding)?;
                if let Some((slot, (a, b))) = p
                    .fields
                    .iter()
                    .zip(&t.fields)
                    .enumerate()
                    .find(|(_, (a, b))| binding.get(a) != Some(b))
                {
                    return Err(at_binding(Diagnostic::new(
                        ErrorKind::InvalidBinding,
                        "field mismatch",
                    ))
                    .at_atom(*a)
                    .at_atom(*b)
                    .at_slot(slot)
                    .into());
                }
            }
        }
    }
    let consumed: BTreeSet<_> = rule
        .lhs
        .difference(&rule.rhs)
        .map(|id| binding[id])
        .collect();
    let context = graph.closure(&image)?;
    ensure(
        rule.meta || context.is_disjoint(&hidden),
        "object grounding enters rule representation",
    )
    .map_err(binding_error)
    .map_err(|error| AdmissionFailure::rejected(error, ErrorKind::InvalidBinding))?;
    let preserved = context.difference(&consumed).copied().collect();
    let mut read = context;
    read.extend(&rule.representation);
    let fresh: Vec<_> = rule.rhs.difference(&rule.lhs).copied().collect();
    let positions: BTreeMap<_, _> = fresh.iter().enumerate().map(|(i, id)| (*id, i)).collect();
    let batch = fresh
        .iter()
        .map(|id| {
            let atom = graph.atom(*id)?;
            let fields = atom
                .fields
                .iter()
                .map(|field| {
                    if let Some(index) = positions.get(field) {
                        Ok(Target::Fresh(*index))
                    } else {
                        binding
                            .get(field)
                            .copied()
                            .map(Target::Existing)
                            .ok_or_else(|| {
                                Diagnostic::new(ErrorKind::InvalidBinding, "unresolved RHS field")
                                    .at_atom(source)
                                    .at_atom(*id)
                                    .at_atom(*field)
                                    .at_role(atom.kind.role())
                            })
                    }
                })
                .collect::<Result<_>>()?;
            Ok(NewAtom {
                kind: atom.kind.clone(),
                fields,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let mut candidate = graph.clone();
    candidate
        .remove_set(&consumed)
        .map_err(|error| AdmissionFailure::rejected(error, ErrorKind::Dangling))?;
    let produced: BTreeSet<_> = candidate
        .insert_batch_with_limits(&batch, limits)?
        .into_iter()
        .collect();
    let after = if framed {
        data_frame(
            graph, &candidate, before, &hidden, &consumed, &produced, limits,
        )
    } else {
        None
    };
    let after = match after {
        Some(certificate) => certificate,
        None => validate_with_limits(&candidate, limits)
            .map_err(|error| AdmissionFailure::rejected(error, ErrorKind::InvalidConfiguration))?,
    };
    let pre_heads: BTreeSet<_> = before.rules.keys().copied().collect();
    let post_heads: BTreeSet<_> = after.rules.keys().copied().collect();
    let entered: BTreeSet<_> = post_heads.difference(&pre_heads).copied().collect();
    let exited: BTreeSet<_> = pre_heads.difference(&post_heads).copied().collect();
    let mut altered = BTreeSet::new();
    for head in &entered {
        ensure(
            produced.contains(&after.rules[head].revision),
            "entry requires fresh revision",
        )
        .map_err(|e| {
            e.with_kind(ErrorKind::Lifecycle)
                .at_atom(*head)
                .at_role(Some(Role::Revision))
        })
        .map_err(|error| AdmissionFailure::rejected(error, ErrorKind::Lifecycle))?;
        for (id, atom) in graph
            .iter()
            .filter(|(_, a)| a.kind.role() == Some(Role::Revision) && a.fields[0] == *head)
        {
            let _ = atom;
            ensure(
                consumed.contains(&id),
                "entry retains an old revision template",
            )
            .map_err(|e| {
                e.with_kind(ErrorKind::Lifecycle)
                    .at_atom(*head)
                    .at_atom(id)
                    .at_role(Some(Role::Revision))
            })
            .map_err(|error| AdmissionFailure::rejected(error, ErrorKind::Lifecycle))?;
        }
    }
    for head in &exited {
        ensure(
            consumed.contains(&before.rules[head].revision),
            "exit must consume executable revision",
        )
        .map_err(|e| {
            e.with_kind(ErrorKind::Lifecycle)
                .at_atom(*head)
                .at_role(Some(Role::Revision))
        })
        .map_err(|error| AdmissionFailure::rejected(error, ErrorKind::Lifecycle))?;
        if candidate.get(*head).is_none() {
            ensure(
                before.rules[head].representation.is_subset(&consumed),
                "head deletion must consume its representation",
            )
            .map_err(|e| e.with_kind(ErrorKind::Lifecycle).at_atom(*head))
            .map_err(|error| AdmissionFailure::rejected(error, ErrorKind::Lifecycle))?;
        }
    }
    for head in pre_heads.intersection(&post_heads) {
        let pre = &before.rules[head];
        let post = &after.rules[head];
        if pre.body != post.body {
            altered.insert(*head);
            ensure(
                consumed.contains(&pre.revision) && produced.contains(&post.revision),
                "alteration requires revision replacement",
            )
            .map_err(|e| {
                e.with_kind(ErrorKind::Lifecycle)
                    .at_atom(*head)
                    .at_role(Some(Role::Revision))
            })
            .map_err(|error| AdmissionFailure::rejected(error, ErrorKind::Lifecycle))?;
        } else {
            ensure(
                pre.revision == post.revision,
                "unchanged rule cannot churn revision",
            )
            .map_err(|e| {
                e.with_kind(ErrorKind::Lifecycle)
                    .at_atom(*head)
                    .at_role(Some(Role::Revision))
            })
            .map_err(|error| AdmissionFailure::rejected(error, ErrorKind::Lifecycle))?;
        }
    }
    for head in entered.union(&altered) {
        ensure(
            after.rules[head].rank < rule.rank,
            "GC: affected post-rank is not below source pre-rank",
        )
        .map_err(|e| {
            e.with_kind(ErrorKind::Guardedness)
                .at_atom(*head)
                .at_atom(source)
                .at_role(Some(Role::Rank))
        })
        .map_err(|error| AdmissionFailure::rejected(error, ErrorKind::Guardedness))?;
    }
    let event = Event {
        source,
        source_revision: rule.revision,
        consumed,
        preserved,
        produced,
        read,
        entered,
        exited,
        altered,
    };
    Ok((candidate, event, after))
}

/// Ordinary-data frame lemma. No membership, metadata, rank, variable or quoted
/// syntax changes. Existing incidences are immutable; checked deletion established
/// the dangling condition. New links have constructor endpoints. Thus all decoded
/// representations and recursive packages are unchanged. The exact full-validator
/// charge changes only with top-level atom/field scan coefficients.
fn data_frame(
    before_graph: &Graph,
    after_graph: &Graph,
    before: &Configuration,
    hidden: &BTreeSet<AtomKey>,
    consumed: &BTreeSet<AtomKey>,
    produced: &BTreeSet<AtomKey>,
    limits: &GraphLimits,
) -> Option<Configuration> {
    // Nested-package validation has additional outer-carrier closure charges;
    // keep the full validator until a separate coefficient certificate covers it.
    if before.rules.values().any(|r| !r.package_atoms.is_empty()) {
        return None;
    }
    let ordinary = |atom: &graph_core::Atom| {
        matches!(
            atom.kind,
            Kind::Constructor(_)
                | Kind::Record {
                    role: Role::ObjectLink,
                    ..
                }
        )
    };
    if !hidden.is_disjoint(consumed)
        || consumed
            .iter()
            .any(|id| !ordinary(before_graph.get(*id).unwrap()))
    {
        return None;
    }
    for id in produced {
        let atom = after_graph.get(*id)?;
        if !ordinary(atom)
            || atom.fields.iter().any(|target| {
                !matches!(
                    after_graph.get(*target).map(|a| &a.kind),
                    Some(Kind::Constructor(_))
                )
            })
        {
            return None;
        }
    }
    let rules = before.rules.len() as i128;
    let active = before.rules.values().filter(|r| r.active).count() as i128;
    let work = (before.validation_work as i128)
        + (2 + 2 * rules + 2 * active) * (after_graph.len() as i128 - before_graph.len() as i128)
        + (rules + 2 * active)
            * (after_graph.field_count() as i128 - before_graph.field_count() as i128);
    let work = usize::try_from(work).ok()?;
    if work > limits.max_validation_work {
        return None;
    }
    let mut after = before.clone();
    after.validation_work = work;
    Some(after)
}

crates/engine/src/matching.rs:
use crate::{AdmissionFailure, CandidateSearch, Execution, OperationalBinding, PreparedStep};
use graph_core::{
    AtomKey, Binding, Configuration, Diagnostic, ErrorKind, Graph, Kind, Result, RuleView, Sort,
};
use std::collections::{BTreeMap, BTreeSet};

/// A raw match rejected by a named applicability predicate, not a search failure.
#[derive(Clone, Debug)]
pub struct RejectedBinding {
    pub binding: OperationalBinding,
    pub diagnostic: Diagnostic,
}

/// Fully examined enabled candidates and expected rejections for one immutable
/// state. On search/resource failure no partial set is returned. Each candidate
/// is independently stamped; committing one invalidates the others.
#[derive(Debug)]
pub struct EnabledSet {
    steps: Vec<PreparedStep>,
    rejected: Vec<RejectedBinding>,
    candidates: usize,
    work: usize,
}
impl EnabledSet {
    pub fn steps(&self) -> &[PreparedStep] {
        &self.steps
    }
    pub fn rejected(&self) -> &[RejectedBinding] {
        &self.rejected
    }
    pub fn into_steps(self) -> Vec<PreparedStep> {
        self.steps
    }
    /// Cumulative complete candidates in the containing CandidateSearch.
    pub fn attempted_candidates(&self) -> usize {
        self.candidates
    }
    pub fn work_used(&self) -> usize {
        self.work
    }
}

impl Execution {
    /// All raw injective pattern matches for one live source. Inactive sources
    /// yield no bindings. Raw matching does not check grounding or applicability.
    pub fn bindings(&self, source: AtomKey) -> Result<Vec<OperationalBinding>> {
        self.search().bindings(source)
    }
    /// Exhaustively examine every active source before returning the enabled set.
    /// Only successful empty all-source results establish absence of an enabled step.
    pub fn enabled(&self) -> Result<EnabledSet> {
        self.search().enabled()
    }
    /// As enabled, restricted to one live source; an empty result is not a global normal form.
    pub fn enabled_for(&self, source: AtomKey) -> Result<EnabledSet> {
        self.search().enabled_for(source)
    }
}

impl CandidateSearch<'_> {
    pub fn bindings(&mut self, source: AtomKey) -> Result<Vec<OperationalBinding>> {
        let result = (|| {
            self.check()?;
            let execution = self.execution;
            let view = execution.view()?;
            let rule = source_rule(view.configuration(), source)?;
            let hidden = hidden(view.configuration(), self)?;
            let mut bindings = Vec::new();
            enumerate(execution.graph(), rule, &hidden, self, |search, binding| {
                search.reserve_candidate(binding.assignments().len())?;
                bindings.push(binding);
                Ok(())
            })?;
            Ok(bindings)
        })();
        self.remember_failure(result)
    }
    pub fn enabled(&mut self) -> Result<EnabledSet> {
        self.enabled_query(None, |_| Ok(()))
    }
    pub fn enabled_for(&mut self, source: AtomKey) -> Result<EnabledSet> {
        self.enabled_query(Some(source), |_| Ok(()))
    }
    pub(crate) fn enabled_retaining(
        &mut self,
        retain: impl FnMut(&PreparedStep) -> Result<()>,
    ) -> Result<EnabledSet> {
        self.enabled_query(None, retain)
    }
    fn enabled_query(
        &mut self,
        source: Option<AtomKey>,
        mut retain: impl FnMut(&PreparedStep) -> Result<()>,
    ) -> Result<EnabledSet> {
        let result = (|| {
            self.check()?;
            let execution = self.execution;
            let view = execution.view()?;
            if let Some(source) = source {
                source_rule(view.configuration(), source)?;
            }
            let hidden = hidden(view.configuration(), self)?;
            let mut steps = Vec::new();
            let mut rejected = Vec::new();
            for rule in view
                .live_rules()
                .filter(|r| source.is_none_or(|s| s == r.head))
            {
                self.charge_work(1)?;
                enumerate(execution.graph(), rule, &hidden, self, |search, binding| {
                    // Retention as well as exploration is bounded by cumulative work.
                    search.charge_work(execution.graph().len())?;
                    match search.prepare_classified(binding.clone()) {
                        Ok(step) => {
                            search.charge_work(step.ground_rule().fresh().len())?;
                            retain(&step)?;
                            steps.push(step);
                        }
                        Err(AdmissionFailure::Rejected(diagnostic)) => {
                            rejected.push(RejectedBinding {
                                binding,
                                diagnostic,
                            })
                        }
                        Err(AdmissionFailure::Failed(error)) => return Err(error),
                    }
                    Ok(())
                })?;
            }
            Ok(EnabledSet {
                steps,
                rejected,
                candidates: self.attempted_candidates(),
                work: self.work_used(),
            })
        })();
        self.remember_failure(result)
    }
}

pub(crate) fn source_rule(configuration: &Configuration, source: AtomKey) -> Result<&RuleView> {
    configuration.rules.get(&source).ok_or_else(|| {
        Diagnostic::new(ErrorKind::InvalidBinding, "enumeration source is not live").at_atom(source)
    })
}
pub(crate) fn hidden(
    configuration: &Configuration,
    search: &mut CandidateSearch<'_>,
) -> Result<BTreeSet<AtomKey>> {
    let mut hidden = BTreeSet::new();
    for rule in configuration.rules.values() {
        search.charge_work(rule.representation.len())?;
        hidden.extend(&rule.representation);
    }
    Ok(hidden)
}

/// Fixed candidate domains, reversible assignments and iterative backtracking.
/// Each complete assignment has exactly one search path; parallel keys stay distinct.
fn enumerate(
    graph: &Graph,
    rule: &RuleView,
    hidden: &BTreeSet<AtomKey>,
    search: &mut CandidateSearch<'_>,
    mut visit: impl FnMut(&mut CandidateSearch<'_>, OperationalBinding) -> Result<()>,
) -> Result<()> {
    if !rule.active {
        return Ok(());
    }
    let mut index: BTreeMap<Sort, Vec<AtomKey>> = BTreeMap::new();
    for (id, atom) in graph.iter() {
        search.charge_work(1)?;
        if rule.meta || !hidden.contains(&id) {
            index.entry(atom.kind.sort()).or_default().push(id);
        }
    }
    let mut assignment = BTreeMap::new();
    let mut used = BTreeSet::new();
    let mut domains = Vec::new();
    for id in &rule.lhs {
        search.charge_work(1)?;
        let pattern = graph.atom(*id)?;
        if matches!(
            pattern.kind,
            Kind::PatternVariable {
                binding: Binding::AppliedRule,
                ..
            }
        ) {
            if !used.insert(rule.head) {
                return Ok(());
            }
            assignment.insert(*id, rule.head);
            continue;
        }
        let sorts = match &pattern.kind {
            Kind::PatternVariable { admits, .. } => admits.clone(),
            kind => BTreeSet::from([kind.sort()]),
        };
        let mut candidates = Vec::new();
        for sort in sorts {
            for target in index.get(&sort).into_iter().flatten() {
                search.charge_work(1)?;
                let atom = graph.atom(*target)?;
                if matches!(pattern.kind, Kind::PatternVariable { .. })
                    || (pattern.kind == atom.kind && pattern.fields.len() == atom.fields.len())
                {
                    candidates.push(*target);
                }
            }
        }
        candidates.sort();
        if candidates.is_empty() {
            return Ok(());
        }
        domains.push((*id, candidates));
    }
    domains.sort_by_key(|(id, candidates)| (candidates.len(), *id));
    let mut next = vec![0; domains.len()];
    let mut depth = 0;
    loop {
        if depth == domains.len() {
            visit(
                search,
                OperationalBinding::new(rule.head, assignment.clone()),
            )?;
            if depth == 0 {
                return Ok(());
            }
            depth -= 1;
            continue;
        }
        let (pattern, candidates) = &domains[depth];
        if let Some(previous) = assignment.remove(pattern) {
            used.remove(&previous);
        }
        let mut advance = false;
        while next[depth] < candidates.len() {
            search.charge_work(1)?;
            let target = candidates[next[depth]];
            next[depth] += 1;
            if !used.insert(target) {
                continue;
            }
            assignment.insert(*pattern, target);
            if feasible(graph, &assignment, search)? {
                advance = true;
                break;
            }
            assignment.remove(pattern);
            used.remove(&target);
        }
        if advance {
            depth += 1;
        } else {
            next[depth] = 0;
            if depth == 0 {
                return Ok(());
            }
            depth -= 1;
        }
    }
}
pub(crate) fn feasible(
    graph: &Graph,
    assignment: &BTreeMap<AtomKey, AtomKey>,
    search: &mut CandidateSearch<'_>,
) -> Result<bool> {
    for (pattern, target) in assignment {
        search.charge_work(1)?;
        let pattern = graph.atom(*pattern)?;
        let atom = graph.atom(*target)?;
        for (field, actual) in pattern.fields.iter().zip(&atom.fields) {
            search.charge_work(1)?;
            if assignment
                .get(field)
                .is_some_and(|expected| expected != actual)
            {
                return Ok(false);
            }
        }
    }
    Ok(true)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn collection_insertion_order_does_not_change_search_with_fixed_atom_keys() {
        let f =
            graph_core::fixture::load(include_str!("../../../examples/fixtures/c1.atoms")).unwrap();
        let execution = Execution::new(f.graph, Default::default()).unwrap();
        let original = execution.view().unwrap().configuration().clone();
        let mut reordered = Configuration::default();
        for (head, rule) in original.rules.iter().rev() {
            let mut rule = rule.clone();
            rule.lhs = rule.lhs.iter().rev().copied().collect();
            rule.rhs = rule.rhs.iter().rev().copied().collect();
            rule.representation = rule.representation.iter().rev().copied().collect();
            reordered.rules.insert(*head, rule);
        }
        reordered.quoted = original
            .quoted
            .iter()
            .rev()
            .map(|(a, b)| (*a, *b))
            .collect();
        reordered.operative_memberships = original
            .operative_memberships
            .iter()
            .rev()
            .copied()
            .collect();
        let mut outputs = Vec::new();
        for config in [&original, &reordered] {
            let mut search = execution.search();
            let hidden = hidden(config, &mut search).unwrap();
            let mut output = Vec::new();
            for rule in config.rules.values() {
                enumerate(execution.graph(), rule, &hidden, &mut search, |s, b| {
                    s.reserve_candidate(b.assignments().len())?;
                    output.push(b);
                    Ok(())
                })
                .unwrap();
            }
            outputs.push((output, search.work_used()));
            search.finish().unwrap();
        }
        assert_eq!(outputs[0], outputs[1]);
    }

    #[test]
    fn unexpected_binding_failure_is_not_an_expected_applicability_rejection() {
        let f =
            graph_core::fixture::load(include_str!("../../../examples/fixtures/b2.atoms")).unwrap();
        let execution = Execution::new(f.graph, Default::default()).unwrap();
        let mut search = execution.search();
        let result =
            search.prepare_classified(OperationalBinding::new(f.names["sl"], BTreeMap::new()));
        assert!(
            matches!(result,Err(AdmissionFailure::Failed(e)) if e.kind()==ErrorKind::InvalidBinding)
        );
        assert!(matches!(
            AdmissionFailure::rejected(
                Diagnostic::exhausted(graph_core::LimitKind::Atoms, "limit"),
                ErrorKind::InvalidConfiguration
            ),
            AdmissionFailure::Failed(_)
        ));
        assert!(matches!(
            AdmissionFailure::rejected(
                Diagnostic::new(
                    ErrorKind::InvalidConfiguration,
                    "unexpected deletion identity"
                ),
                ErrorKind::Dangling
            ),
            AdmissionFailure::Failed(_)
        ));
    }
}

crates/engine/src/meta_activity.rs:
//! Offline relative-termination analysis. No change to GC or runtime admission.
//! The native entry point builds every edge itself; supplied abstract edges or
//! potentials never authorise execution or assert matcher completeness.
use crate::observation::{self, Budget, Observation, ObservationLimits};
use crate::stability::{Contract, Limits, Status};
use crate::Execution;
use graph_core::{Binding, Diagnostic, ErrorKind, Graph, Kind, LimitKind, Result, Sort};
use serde::Serialize;
use std::collections::VecDeque;

#[derive(Clone, Debug, Serialize)]
pub struct Edge {
    pub from: usize,
    pub to: usize,
    pub source: u64,
    pub source_revision: u64,
    pub binding: Vec<(u64, u64)>,
    pub entered: Vec<u64>,
    pub exited: Vec<u64>,
    pub altered: Vec<u64>,
    pub meta_source: bool,
    pub object_progress: bool,
}
impl Edge {
    pub fn edits(&self) -> bool {
        !(self.entered.is_empty() && self.exited.is_empty() && self.altered.is_empty())
    }
}

#[derive(Clone, Debug, Serialize)]
pub struct Bound {
    pub verdict: &'static str,
    pub initial_bound: Option<usize>,
    pub maximum_bound: Option<usize>,
    /// A nonincreasing credit on zero-cost steps; strict on unit-cost steps.
    pub potential: Vec<usize>,
    /// Indices into the supplied edge list forming a positive-cost cycle.
    pub cycle_edges: Vec<usize>,
}

/// Verify a supplied abstract potential, not the completeness of its edge list.
pub fn verify_potential(
    states: usize,
    edges: &[(usize, usize, bool)],
    potential: &[usize],
) -> bool {
    potential.len() == states
        && edges.iter().all(|&(a, b, w)| {
            a < states
                && b < states
                && potential[b]
                    .checked_add(usize::from(w))
                    .is_some_and(|n| potential[a] >= n)
        })
}

/// Weighted finite-graph criterion. All vertices are included; native callers
/// supply only reachable classes. Resource exhaustion never means refutation.
pub fn weighted_bound(
    states: usize,
    edges: &[(usize, usize, bool)],
    max_work: usize,
) -> Result<Bound> {
    let mut budget = Budget::new(max_work, LimitKind::ComparisonWork);
    bound(states, edges, &mut budget)
}

fn bound(states: usize, edges: &[(usize, usize, bool)], budget: &mut Budget) -> Result<Bound> {
    if states == 0 || edges.iter().any(|&(a, b, _)| a >= states || b >= states) {
        return Err(Diagnostic::new(
            ErrorKind::MalformedInput,
            "invalid finite weighted graph",
        ));
    }
    budget.charge(states.saturating_add(edges.len()))?;
    let mut potential = vec![0usize; states];
    for _ in 0..states {
        budget.charge(states)?;
        let old = potential.clone();
        let mut changed = false;
        for &(a, b, w) in edges {
            budget.charge(1)?;
            let value = old[b] + usize::from(w);
            if value > potential[a] {
                potential[a] = value;
                changed = true;
            }
        }
        if !changed {
            debug_assert!(verify_potential(states, edges, &potential));
            return Ok(Bound {
                verdict: "certified",
                initial_bound: Some(potential[0]),
                maximum_bound: potential.iter().copied().max(),
                potential,
                cycle_edges: Vec::new(),
            });
        }
    }
    // A positive cycle exists. Recover one using a positive edge plus a path
    // back to its source. The witness includes zero-cost administrative steps.
    let mut outgoing = vec![Vec::new(); states];
    for (i, &(a, _, _)) in edges.iter().enumerate() {
        outgoing[a].push(i);
    }
    for (first, &(a, b, w)) in edges.iter().enumerate() {
        if !w {
            continue;
        }
        budget.charge(states)?;
        let mut previous: Vec<Option<usize>> = vec![None; states];
        let mut seen = vec![false; states];
        seen[b] = true;
        let mut queue = VecDeque::from([b]);
        while let Some(at) = queue.pop_front() {
            if at == a {
                let mut path = Vec::new();
                let mut at = a;
                while at != b {
                    let i = previous[at].expect("reached by a path");
                    path.push(i);
                    at = edges[i].0;
                }
                path.reverse();
                let mut cycle = vec![first];
                cycle.extend(path);
                return Ok(Bound {
                    verdict: "refuted",
                    initial_bound: None,
                    maximum_bound: None,
                    potential: Vec::new(),
                    cycle_edges: cycle,
                });
            }
            for &i in &outgoing[at] {
                budget.charge(1)?;
                let to = edges[i].1;
                if !seen[to] {
                    seen[to] = true;
                    previous[to] = Some(i);
                    queue.push_back(to);
                }
            }
        }
    }
    unreachable!("a growing nth relaxation requires a positive cycle")
}

#[derive(Clone, Debug, Serialize)]
pub struct Recovery {
    pub verdict: &'static str,
    pub bound: Option<usize>,
    pub closed: bool,
    pub stable_output: bool,
    pub agreement: bool,
}
#[derive(Clone, Debug, Serialize)]
pub struct Abstraction {
    pub kind: &'static str,
    pub label: String,
    pub initially_erased: usize,
    /// Sum over explored representative edges, NOT an execution's garbage count.
    pub edge_erasure_count: usize,
}
#[derive(Clone, Debug, Serialize)]
pub struct Report {
    pub schema: &'static str,
    pub complete: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub abstraction: Option<Abstraction>,
    pub states: usize,
    pub edges: Vec<Edge>,
    pub legitimate: Option<Vec<bool>>,
    pub total_edits: Bound,
    pub edit_burst: Bound,
    pub meta_invocations: Bound,
    pub meta_burst: Bound,
    pub edits_without_object_progress: Option<Bound>,
    pub recovery: Option<Recovery>,
    pub productive_modulation: Option<&'static str>,
}
struct State {
    execution: Execution,
    observation: Observation,
    status: Status,
    legitimate: bool,
    unresolved: usize,
}

/// Complete full-carrier exploration with optional protected-payload contract.
/// Progress means an object-mode step reduces the number of unmet requirements.
/// It is an explicitly chosen task measure, not an intrinsic notion of usefulness.
pub fn analyse(graph: Graph, contract: Option<&Contract>, limits: Limits) -> Result<Report> {
    analyse_impl(graph, contract, limits, None)
}

/// Erase only isolated constructors of a selected label in private analysis
/// representatives. Check every reachable state's active patterns for possible
/// access. This is not runtime GC, a payload-only projection or a fairness rule.
pub fn analyse_inert(
    graph: Graph,
    contract: Option<&Contract>,
    limits: Limits,
    label: &str,
) -> Result<Report> {
    analyse_impl(graph, contract, limits, Some(label))
}

/// Local obligation checker, also useful for conformance tests. Successful
/// projection alone does NOT prove future revisions preserve noninterference.
pub fn project_inert(execution: &Execution, label: &str, limits: Limits) -> Result<(Graph, usize)> {
    let mut budget = Budget::new(limits.max_comparison_work, LimitKind::ComparisonWork);
    project(execution, label, &mut budget)
}

fn project(execution: &Execution, label: &str, budget: &mut Budget) -> Result<(Graph, usize)> {
    let graph = execution.graph();
    budget.charge(graph.retention_units())?;
    // Active LHSs are record-closed. A contextual reference to a candidate atom
    // is impossible when that atom has zero incoming incidence.
    for rule in execution.view()?.active_rules() {
        for id in &rule.lhs {
            budget.charge(1)?;
            let unsafe_access = match &graph.atom(*id)?.kind {
                Kind::Constructor(s) => s == label,
                Kind::PatternVariable { admits, binding } => {
                    *binding == Binding::Free && admits.contains(&Sort::Constructor)
                }
                _ => false,
            };
            if unsafe_access {
                return Err(Diagnostic::new(
                    ErrorKind::InvalidBinding,
                    "unsupported inert abstraction: an active pattern can read the erased label",
                )
                .at_atom(rule.head)
                .at_atom(*id));
            }
        }
    }
    let mut erased = std::collections::BTreeSet::new();
    for (id, atom) in graph.iter() {
        if matches!(&atom.kind, Kind::Constructor(s) if s == label) {
            budget.charge(1)?;
            let incoming = graph.references_to(id);
            budget.charge(incoming.len())?;
            if incoming.is_empty() {
                erased.insert(id);
            }
        }
    }
    let mut projected = graph.clone();
    projected.remove_set(&erased)?;
    Ok((projected, erased.len()))
}

fn analyse_impl(
    graph: Graph,
    contract: Option<&Contract>,
    limits: Limits,
    label: Option<&str>,
) -> Result<Report> {
    let names = contract.map(Contract::names).transpose()?;
    if label.is_some_and(|s| names.as_ref().is_some_and(|names| names.contains(s))) {
        return Err(Diagnostic::new(
            ErrorKind::InvalidBinding,
            "unsupported inert abstraction: declared payload uses erased label",
        ));
    }
    let mut budget = Budget::new(limits.max_comparison_work, LimitKind::ComparisonWork);
    let mut first = Execution::new(graph, limits.execution)?;
    let mut abstraction = None;
    if let Some(label) = label {
        let (g, n) = project(&first, label, &mut budget)?;
        first = Execution::new(g, limits.execution)?;
        abstraction = Some(Abstraction {
            kind: "isolated-inert-constructors-v1",
            label: label.into(),
            initially_erased: n,
            edge_erasure_count: 0,
        });
    }
    let (anchors, status, legitimate) = if let Some(c) = contract {
        c.inspect(&first, names.as_ref().unwrap(), None)?
    } else {
        Default::default()
    };
    let unresolved = count_unresolved(contract, &status)?;
    let ol = ObservationLimits {
        max_work: limits.max_retained_units,
        max_history_units: limits.max_retained_units,
        max_comparison_work: limits.max_comparison_work,
    };
    let observation = observation::all(first.graph(), limits.execution.graph, ol)?;
    let mut units = observation.retention_units() + status_units(&status);
    check_units(units, limits)?;
    if limits.max_states == 0 {
        return Err(exhausted("meta state bound"));
    }
    let mut states = vec![State {
        execution: first,
        observation,
        status,
        legitimate,
        unresolved,
    }];
    let mut edges = Vec::new();
    let mut cursor = 0;
    while cursor < states.len() {
        let enabled = states[cursor].execution.enabled()?;
        for step in enabled.into_steps() {
            if edges.len() >= limits.max_edges {
                return Err(exhausted("meta edge bound"));
            }
            let meta_source = states[cursor].execution.view()?.configuration().rules
                [&step.binding().source()]
                .meta;
            let mut branch = states[cursor].execution.fork();
            let prepared = branch.prepare(step.binding().clone())?;
            let event = branch.commit(prepared)?;
            if let Some(a) = &mut abstraction {
                let (g, n) = project(&branch, &a.label, &mut budget)?;
                a.edge_erasure_count = a
                    .edge_erasure_count
                    .checked_add(n)
                    .ok_or_else(|| exhausted("erasure count overflow"))?;
                branch = Execution::new(g, limits.execution)?;
            }
            let (_, status, legitimate) = if let Some(c) = contract {
                c.inspect(&branch, names.as_ref().unwrap(), Some(&anchors))?
            } else {
                Default::default()
            };
            let unresolved = count_unresolved(contract, &status)?;
            let object_progress = !meta_source && unresolved < states[cursor].unresolved;
            let observation = observation::all(branch.graph(), limits.execution.graph, ol)?;
            let mut found = None;
            for (i, s) in states.iter().enumerate() {
                budget.charge(1 + status_units(&status))?;
                if s.status == status
                    && s.observation.signature() == observation.signature()
                    && observation::isomorphic_indexed_budget(
                        &s.observation,
                        &observation,
                        &mut budget,
                    )?
                {
                    found = Some(i);
                    break;
                }
            }
            let to = found.unwrap_or(states.len());
            if found.is_none() {
                if states.len() >= limits.max_states {
                    return Err(exhausted("meta state bound"));
                }
                units = units
                    .saturating_add(observation.retention_units())
                    .saturating_add(status_units(&status));
                check_units(units, limits)?;
                states.push(State {
                    execution: branch,
                    observation,
                    status,
                    legitimate,
                    unresolved,
                });
            }
            units = units.saturating_add(
                9 + step.binding().assignments().len() * 2
                    + event.entered.len()
                    + event.exited.len()
                    + event.altered.len(),
            );
            check_units(units, limits)?;
            edges.push(Edge {
                from: cursor,
                to,
                source: event.source.number(),
                source_revision: event.source_revision.number(),
                binding: step
                    .binding()
                    .assignments()
                    .iter()
                    .map(|(a, b)| (a.number(), b.number()))
                    .collect(),
                entered: event.entered.iter().map(|k| k.number()).collect(),
                exited: event.exited.iter().map(|k| k.number()).collect(),
                altered: event.altered.iter().map(|k| k.number()).collect(),
                meta_source,
                object_progress,
            });
        }
        cursor += 1;
    }
    // Reserve result vectors and weighted edge copies before constructing them.
    units = units
        .saturating_add(states.len().saturating_mul(24))
        .saturating_add(edges.len().saturating_mul(16));
    check_units(units, limits)?;
    let weighted: Vec<_> = edges.iter().map(|e| (e.from, e.to, e.edits())).collect();
    let total_edits = bound(states.len(), &weighted, &mut budget)?;
    let edit_burst = bound(
        states.len(),
        &weighted.iter().copied().filter(|e| e.2).collect::<Vec<_>>(),
        &mut budget,
    )?;
    let meta_invocations = bound(
        states.len(),
        &edges
            .iter()
            .map(|e| (e.from, e.to, e.meta_source))
            .collect::<Vec<_>>(),
        &mut budget,
    )?;
    let meta_ids: Vec<_> = edges
        .iter()
        .enumerate()
        .filter(|(_, e)| e.meta_source)
        .map(|(i, _)| i)
        .collect();
    let mut meta_burst = bound(
        states.len(),
        &meta_ids
            .iter()
            .map(|&i| (edges[i].from, edges[i].to, true))
            .collect::<Vec<_>>(),
        &mut budget,
    )?;
    for i in &mut meta_burst.cycle_edges {
        *i = meta_ids[*i];
    }
    let mut report = Report {
        schema: if abstraction.is_some() {
            "meta-activity-analysis-v2"
        } else {
            "meta-activity-analysis-v1"
        },
        complete: true,
        abstraction,
        states: states.len(),
        edges,
        legitimate: None,
        total_edits,
        edit_burst,
        meta_invocations,
        meta_burst,
        edits_without_object_progress: None,
        recovery: None,
        productive_modulation: None,
    };
    // Translate filtered-graph witness indices back to the report's edge IDs.
    let edit_ids: Vec<_> = report
        .edges
        .iter()
        .enumerate()
        .filter(|(_, e)| e.edits())
        .map(|(i, _)| i)
        .collect();
    for i in &mut report.edit_burst.cycle_edges {
        *i = edit_ids[*i];
    }
    if let Some(contract) = contract {
        let legitimate: Vec<_> = states.iter().map(|s| s.legitimate).collect();
        let mut successors = vec![Vec::new(); states.len()];
        for e in &report.edges {
            successors[e.from].push(e.to);
        }
        let closed = report
            .edges
            .iter()
            .all(|e| !legitimate[e.from] || legitimate[e.to]);
        let stable_output = report
            .edges
            .iter()
            .all(|e| !legitimate[e.from] || states[e.from].status == states[e.to].status);
        let ranks = crate::stability::rank_quotient(&legitimate, &successors).ok();
        let first_output = states.iter().find(|s| s.legitimate).map(|s| &s.status);
        let agreement = first_output.is_some()
            && states
                .iter()
                .filter(|s| s.legitimate)
                .all(|s| Some(&s.status) == first_output);
        let good = closed
            && (!contract.stable_when_legitimate || stable_output)
            && (!contract.require_agreement || agreement)
            && ranks.is_some();
        report.recovery = Some(Recovery {
            verdict: if good { "certified" } else { "refuted" },
            bound: if good {
                Some(ranks.as_ref().unwrap()[0].unwrap_or(0))
            } else {
                None
            },
            closed,
            stable_output,
            agreement,
        });
        let ids: Vec<_> = report
            .edges
            .iter()
            .enumerate()
            .filter(|(_, e)| !legitimate[e.from] && !e.object_progress)
            .map(|(i, _)| i)
            .collect();
        let mut b = bound(
            states.len(),
            &ids.iter().map(|&i| weighted[i]).collect::<Vec<_>>(),
            &mut budget,
        )?;
        for i in &mut b.cycle_edges {
            *i = ids[*i];
        }
        report.productive_modulation = Some(if good && stable_output && b.verdict == "certified" {
            "certified"
        } else {
            "refuted"
        });
        report.edits_without_object_progress = Some(b);
        report.legitimate = Some(legitimate);
    }
    Ok(report)
}
fn count_unresolved(c: Option<&Contract>, status: &Status) -> Result<usize> {
    let Some(c) = c else { return Ok(0) };
    if status.iter().any(|s| s.len() != 1) {
        return Err(Diagnostic::new(
            ErrorKind::InvalidBinding,
            "meta progress requires singleton declared statuses",
        ));
    }
    Ok(c.requirements
        .iter()
        .zip(status)
        .filter(|(r, s)| !r.legitimate_labels.contains(&s[0].0))
        .count())
}
fn status_units(status: &Status) -> usize {
    status.iter().flatten().fold(status.len(), |n, (a, b)| {
        n.saturating_add(2)
            .saturating_add(a.len())
            .saturating_add(b.len())
    })
}
fn exhausted(s: &str) -> Diagnostic {
    Diagnostic::exhausted(LimitKind::ObservationHistory, s)
}
fn check_units(n: usize, l: Limits) -> Result<()> {
    if n > l.max_retained_units {
        Err(exhausted("meta retention bound"))
    } else {
        Ok(())
    }
}

crates/engine/src/observation.rs:
//! Closed carrier observations and bounded exact isomorphism. These are not
//! executable configurations, and revision identity continuity is not tested.
use graph_core::{
    Atom, AtomKey, Diagnostic, ErrorKind, Graph, Kind, LimitKind, Result, ValidatedGraph,
};
use std::collections::{BTreeMap, BTreeSet};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ObservationLimits {
    pub max_work: usize,
    pub max_comparison_work: usize,
    pub max_history_units: usize,
}
impl Default for ObservationLimits {
    fn default() -> Self {
        Self {
            max_work: 1_000_000,
            max_comparison_work: 1_000_000,
            max_history_units: 1_000_000,
        }
    }
}
pub(crate) struct Budget {
    remaining: usize,
    kind: LimitKind,
}
impl Budget {
    pub(crate) fn new(remaining: usize, kind: LimitKind) -> Self {
        Self { remaining, kind }
    }
    pub(crate) fn charge(&mut self, n: usize) -> Result<()> {
        self.remaining = self.remaining.checked_sub(n).ok_or_else(|| {
            Diagnostic::exhausted(self.kind, "observation/comparison budget exhausted")
        })?;
        Ok(())
    }
}
#[derive(Clone, Debug)]
pub struct Observation {
    atoms: BTreeMap<AtomKey, Atom>,
}
impl Observation {
    pub(crate) fn signature(&self) -> (usize, usize, u64) {
        (
            self.atoms.len(),
            self.atoms.values().map(|a| a.fields.len()).sum(),
            self.atoms.values().fold(0u64, |h, a| {
                h.wrapping_add(graph_core::shape_contribution(a))
            }),
        )
    }
    pub fn atoms(&self) -> &BTreeMap<AtomKey, Atom> {
        &self.atoms
    }
    pub fn retention_units(&self) -> usize {
        self.atoms.values().fold(1usize, |n, a| {
            n.saturating_add(1 + a.fields.len())
                .saturating_add(match &a.kind {
                    Kind::Constructor(s) | Kind::Record { label: Some(s), .. } => s.len(),
                    Kind::PatternVariable { admits, .. } => admits.len(),
                    _ => 0,
                })
        })
    }
    /// Example criterion: distinct endpoints of non-self value links. This is
    /// an externally chosen measure, not an intrinsic definition of meaning.
    pub fn value_payload(&self) -> usize {
        self.atoms.values().filter(|a| matches!(&a.kind, Kind::Record { role: graph_core::Role::ObjectLink, label: Some(s) } if s == "value") && a.fields.len()==2 && a.fields[0]!=a.fields[1])
            .flat_map(|a| a.fields.iter().copied()).collect::<BTreeSet<_>>().len()
    }
}

#[derive(Clone, Debug)]
pub struct Observer {
    canonical: String,
    all: bool,
    data: bool,
    clauses: BTreeSet<(String, String)>,
    inputs: BTreeMap<String, AtomKey>,
}
fn malformed(message: &str) -> Diagnostic {
    Diagnostic::new(ErrorKind::MalformedInput, message)
}
fn decode_hex(s: &str) -> Result<String> {
    if s.len() % 2 != 0
        || !s
            .bytes()
            .all(|c| c.is_ascii_digit() || (b'a'..=b'f').contains(&c))
    {
        return Err(malformed("invalid lowercase UTF-8 hex label"));
    }
    let bytes = s
        .as_bytes()
        .chunks_exact(2)
        .map(|p| {
            let digit = |c: u8| if c <= b'9' { c - b'0' } else { c - b'a' + 10 };
            digit(p[0]) * 16 + digit(p[1])
        })
        .collect();
    String::from_utf8(bytes).map_err(|_| malformed("label is not UTF-8"))
}
impl Observer {
    pub(crate) fn is_all(&self) -> bool {
        self.all
    }
    pub fn initial_inputs(&self) -> &BTreeMap<String, AtomKey> {
        &self.inputs
    }
    pub fn all() -> Self {
        Self {
            canonical: "observer-v1\nall\n".into(),
            all: true,
            data: false,
            clauses: BTreeSet::new(),
            inputs: BTreeMap::new(),
        }
    }
    pub fn parse(
        text: &str,
        mut resolve: impl FnMut(&str) -> Option<AtomKey>,
        max_bytes: usize,
    ) -> Result<Self> {
        if text.len() > max_bytes {
            return Err(Diagnostic::exhausted(
                LimitKind::InputBytes,
                "observer declaration exceeds byte bound",
            ));
        }
        if !text.ends_with('\n') || text.contains('\r') {
            return Err(malformed("observer requires LF and a final LF"));
        }
        let mut lines = text[..text.len() - 1].split('\n');
        if lines.next() != Some("observer-v1") {
            return Err(malformed("unsupported observer schema"));
        }
        let scope = lines
            .next()
            .ok_or_else(|| malformed("missing observer scope"))?;
        if scope == "all" {
            if lines.next().is_some() {
                return Err(malformed("all takes no clauses"));
            }
            return Ok(Self::all());
        }
        if scope != "select carrier" && scope != "select data" {
            return Err(malformed("invalid observer scope"));
        }
        let mut result = Self {
            canonical: String::new(),
            all: false,
            data: scope == "select data",
            clauses: BTreeSet::new(),
            inputs: BTreeMap::new(),
        };
        for line in lines {
            let (selector, value) = line
                .split_once(' ')
                .ok_or_else(|| malformed("invalid observer clause"))?;
            match selector {
                "kind"
                    if [
                        "Constructor",
                        "PatternVariable",
                        "RuleHead",
                        "Nat",
                        "Record",
                    ]
                    .contains(&value) => {}
                "role"
                    if [
                        "ObjectLink",
                        "Lhs",
                        "Rhs",
                        "Active",
                        "Rank",
                        "ModeObject",
                        "ModeMeta",
                        "Revision",
                    ]
                    .contains(&value) => {}
                "constructor" | "link" => {
                    decode_hex(value)?;
                }
                "input" => {
                    if value.is_empty()
                        || !value.bytes().enumerate().all(|(i, c)| {
                            c == b'_' || c.is_ascii_alphabetic() || (i > 0 && c.is_ascii_digit())
                        })
                    {
                        return Err(malformed("invalid input name"));
                    }
                    result.inputs.insert(
                        value.into(),
                        resolve(value).ok_or_else(|| malformed("unresolved observer input"))?,
                    );
                }
                _ => return Err(malformed("unknown observer selector or value")),
            }
            if !result.clauses.insert((selector.into(), value.into())) {
                return Err(malformed("duplicate observer clause"));
            }
        }
        result.canonical = format!("observer-v1\n{scope}\n");
        for (selector, value) in &result.clauses {
            result.canonical += &format!("{selector} {value}\n");
        }
        Ok(result)
    }
    pub fn canonical(&self) -> &str {
        &self.canonical
    }
    /// Caller-supplied initial input identity plus this canonical declaration
    /// and frozen resolution map identify an experiment's observer.
    pub fn identity(&self) -> String {
        format!("{:?}; inputs={:?}", self.canonical, self.inputs)
    }
    pub fn project(
        &self,
        view: &ValidatedGraph<'_>,
        limits: ObservationLimits,
    ) -> Result<Observation> {
        let graph = view.graph();
        let mut budget = Budget::new(limits.max_work, LimitKind::ObservationWork);
        budget.charge(1)?;
        let mut hidden = BTreeSet::new();
        if self.data {
            for rule in view.live_rules() {
                for key in &rule.representation {
                    budget.charge(1)?;
                    hidden.insert(*key);
                }
            }
        }
        let mut seeds = BTreeSet::new();
        for (key, atom) in graph.iter() {
            budget.charge(1)?;
            if self.all {
                seeds.insert(key);
                continue;
            }
            if hidden.contains(&key) {
                continue;
            }
            for (selector, value) in &self.clauses {
                budget.charge(1 + value.len())?;
                let matches = match selector.as_str() {
                    "kind" => match &atom.kind {
                        Kind::Constructor(_) => value == "Constructor",
                        Kind::PatternVariable { .. } => value == "PatternVariable",
                        Kind::RuleHead => value == "RuleHead",
                        Kind::Nat => value == "Nat",
                        Kind::Record { .. } => value == "Record",
                    },
                    "role" => atom.kind.role().is_some_and(|r| format!("{r:?}") == *value),
                    "constructor" => {
                        matches!(&atom.kind,Kind::Constructor(s) if *s==decode_hex(value)?)
                    }
                    "link" => {
                        matches!(&atom.kind,Kind::Record{role:graph_core::Role::ObjectLink,label:Some(s)} if *s==decode_hex(value)?)
                    }
                    "input" => self.inputs.get(value) == Some(&key),
                    _ => false,
                };
                if matches {
                    seeds.insert(key);
                    break;
                }
            }
        }
        let mut pending: Vec<_> = seeds.iter().copied().collect();
        while let Some(key) = pending.pop() {
            for target in &graph.atom(key)?.fields {
                budget.charge(1)?;
                if seeds.insert(*target) {
                    pending.push(*target);
                }
            }
        }
        let mut atoms = BTreeMap::new();
        for key in seeds {
            let atom = graph.atom(key)?;
            budget.charge(
                1 + atom.fields.len()
                    + match &atom.kind {
                        Kind::Constructor(s) | Kind::Record { label: Some(s), .. } => s.len(),
                        Kind::PatternVariable { admits, .. } => admits.len(),
                        _ => 0,
                    },
            )?;
            atoms.insert(key, atom.clone());
        }
        Ok(Observation { atoms })
    }
}

/// Exact iterative bijection search; no hash equality is accepted as evidence.
/// Attribute scans, pair trials and field consistency checks consume one shared
/// budget. This deliberately simple implementation has exponential worst case.
pub fn isomorphic(left: &Observation, right: &Observation, max_work: usize) -> Result<bool> {
    let mut budget = Budget::new(max_work, LimitKind::ComparisonWork);
    isomorphic_budget(left, right, &mut budget)
}
pub(crate) fn isomorphic_budget(
    left: &Observation,
    right: &Observation,
    budget: &mut Budget,
) -> Result<bool> {
    compare_budget(left, right, budget, false)
}

/// Exact comparison with a checked identity witness and incremental, reversible
/// field propagation. Work accounting is deliberately separate from the legacy
/// comparator; callers must not substitute this inside a legacy trace replay.
pub fn isomorphic_indexed(
    left: &Observation,
    right: &Observation,
    max_work: usize,
) -> Result<bool> {
    let mut budget = Budget::new(max_work, LimitKind::ComparisonWork);
    isomorphic_indexed_budget(left, right, &mut budget)
}

pub(crate) fn isomorphic_indexed_budget(
    left: &Observation,
    right: &Observation,
    budget: &mut Budget,
) -> Result<bool> {
    compare_budget(left, right, budget, true)
}

fn compare_budget(
    left: &Observation,
    right: &Observation,
    budget: &mut Budget,
    indexed: bool,
) -> Result<bool> {
    budget.charge(1)?;
    if left.atoms.len() != right.atoms.len() {
        return Ok(false);
    }
    if indexed {
        // Keys alone are NOT a witness. Check all kinds, attributes and ordered
        // endpoints; exact map equality certifies the identity bijection.
        budget.charge(left.retention_units())?;
        budget.charge(right.retention_units())?;
        if left.atoms == right.atoms {
            return Ok(true);
        }
    }
    budget.charge(left.atoms.len())?;
    budget.charge(right.atoms.len())?;
    budget.charge(left.retention_units())?;
    budget.charge(right.retention_units())?;
    let mut l: Vec<_> = left.atoms.iter().collect();
    // Field-bearing atoms constrain several identities at once. Precharge a
    // conservative n log2(n) sorting allowance; this is not a timing estimate.
    budget.charge(
        l.len()
            .saturating_mul(usize::BITS as usize - l.len().leading_zeros() as usize),
    )?;
    l.sort_by_key(|(key, atom)| (std::cmp::Reverse(atom.fields.len()), **key));
    let r: Vec<_> = right.atoms.iter().collect();
    let n = l.len();
    if n == 0 {
        return Ok(true);
    }
    let li: BTreeMap<_, _> = l.iter().enumerate().map(|(i, (k, _))| (**k, i)).collect();
    let ri: BTreeMap<_, _> = r.iter().enumerate().map(|(i, (k, _))| (**k, i)).collect();
    let mut initial_classes = BTreeMap::new();
    let mut colours = Vec::new();
    let mut fields = Vec::new();
    for (offset, atoms, indices) in [(0, &l, &li), (n, &r, &ri)] {
        for (_, atom) in atoms {
            budget.charge(1 + atom.fields.len())?;
            let label = format!("{:?}", atom.kind);
            budget.charge(label.len())?;
            let next = initial_classes.len();
            colours.push(
                *initial_classes
                    .entry((label, atom.fields.len()))
                    .or_insert(next),
            );
            fields.push(
                atom.fields
                    .iter()
                    .map(|k| indices[k] + offset)
                    .collect::<Vec<_>>(),
            );
        }
    }
    let Some(colours) = refine(colours, &fields, n, budget)? else {
        return Ok(false);
    };
    if indexed {
        return propagated(&l, &r, &fields, &colours, budget);
    }
    let mut map = vec![None; n];
    let mut used = vec![false; n];
    let mut next = vec![0; n];
    let mut depth = 0;
    loop {
        if depth == n {
            return Ok(true);
        }
        if next[depth] == n {
            next[depth] = 0;
            if depth == 0 {
                return Ok(false);
            }
            depth -= 1;
            used[map[depth].take().unwrap()] = false;
            continue;
        }
        let candidate = next[depth];
        next[depth] += 1;
        budget.charge(1)?;
        if used[candidate] || colours[depth] != colours[n + candidate] {
            continue;
        }
        let a = l[depth].1;
        let b = r[candidate].1;
        budget.charge(
            1 + match &a.kind {
                Kind::Constructor(s) | Kind::Record { label: Some(s), .. } => s.len(),
                Kind::PatternVariable { admits, .. } => admits.len(),
                _ => 0,
            },
        )?;
        if a.kind != b.kind || a.fields.len() != b.fields.len() {
            continue;
        }
        map[depth] = Some(candidate);
        let mut valid = true;
        let mut forward = BTreeMap::new();
        let mut backward = BTreeMap::new();
        for i in 0..=depth {
            budget.charge(1)?;
            let j = map[i].unwrap();
            if forward.insert(i, j).is_some_and(|old| old != j)
                || backward.insert(j, i).is_some_and(|old| old != i)
            {
                valid = false;
                break;
            }
            for (x, y) in l[i].1.fields.iter().zip(&r[j].1.fields) {
                budget.charge(1)?;
                let x = li[x];
                let y = ri[y];
                if map[x].is_some_and(|target| target != y)
                    || forward.insert(x, y).is_some_and(|old| old != y)
                    || backward.insert(y, x).is_some_and(|old| old != x)
                {
                    valid = false;
                    break;
                }
            }
            if !valid {
                break;
            }
        }
        if valid {
            used[candidate] = true;
            depth += 1;
        } else {
            map[depth] = None;
        }
    }
}

/// Each assigned pair forces its ordered field pairs. The trail records only
/// newly assigned pairs, so undo restores the exact preceding partial bijection.
/// Refinement only restricts domains; success still requires a total bijection.
fn propagated(
    left: &[(&AtomKey, &Atom)],
    right: &[(&AtomKey, &Atom)],
    fields: &[Vec<usize>],
    colours: &[usize],
    budget: &mut Budget,
) -> Result<bool> {
    use std::ops::Bound::{Excluded, Unbounded};
    let n = left.len();
    budget.charge(n.saturating_mul(4))?;
    let mut forward = vec![None; n];
    let mut backward = vec![None; n];
    let mut free: BTreeSet<_> = (0..n).collect();
    let mut available: BTreeMap<usize, BTreeSet<usize>> = BTreeMap::new();
    for i in 0..n {
        available.entry(colours[n + i]).or_default().insert(i);
    }
    struct Frame {
        node: usize,
        last: Option<usize>,
        start: usize,
    }
    let mut stack = vec![Frame {
        node: 0,
        last: None,
        start: 0,
    }];
    let mut trail: Vec<(usize, usize)> = Vec::new();
    while let Some(frame) = stack.last_mut() {
        while trail.len() > frame.start {
            budget.charge(1)?;
            let (a, b) = trail.pop().unwrap();
            forward[a] = None;
            backward[b] = None;
            free.insert(a);
            available.get_mut(&colours[n + b]).unwrap().insert(b);
        }
        budget.charge(1)?;
        let domain = &available[&colours[frame.node]];
        let candidate = match frame.last {
            None => domain.first().copied(),
            Some(last) => domain.range((Excluded(last), Unbounded)).next().copied(),
        };
        let Some(candidate) = candidate else {
            stack.pop();
            continue;
        };
        frame.last = Some(candidate);
        let mut pending = vec![(frame.node, candidate)];
        let mut valid = true;
        while let Some((a, b)) = pending.pop() {
            budget.charge(1)?;
            if let Some(old) = forward[a] {
                if old != b {
                    valid = false;
                    break;
                }
                continue;
            }
            budget.charge(
                1 + match &left[a].1.kind {
                    Kind::Constructor(s) | Kind::Record { label: Some(s), .. } => s.len(),
                    Kind::PatternVariable { admits, .. } => admits.len(),
                    _ => 0,
                },
            )?;
            if backward[b].is_some()
                || colours[a] != colours[n + b]
                || left[a].1.kind != right[b].1.kind
                || fields[a].len() != fields[n + b].len()
            {
                valid = false;
                break;
            }
            forward[a] = Some(b);
            backward[b] = Some(a);
            free.remove(&a);
            available.get_mut(&colours[n + b]).unwrap().remove(&b);
            trail.push((a, b));
            budget.charge(fields[a].len())?;
            pending.extend(
                fields[a]
                    .iter()
                    .zip(&fields[n + b])
                    .map(|(x, y)| (*x, *y - n)),
            );
        }
        if valid {
            let Some(node) = free.first().copied() else {
                return Ok(true);
            };
            stack.push(Frame {
                node,
                last: None,
                start: trail.len(),
            });
        }
    }
    Ok(false)
}

/// Necessary-condition partition refinement only. Incoming signatures are
/// accumulated in one incidence pass, independently of the test oracle's
/// all-pairs construction. Equal partitions still require exact bijection search.
fn refine(
    mut colours: Vec<usize>,
    fields: &[Vec<usize>],
    n: usize,
    budget: &mut Budget,
) -> Result<Option<Vec<usize>>> {
    loop {
        budget.charge(colours.len())?;
        let mut incoming = vec![Vec::new(); colours.len()];
        for (source, targets) in fields.iter().enumerate() {
            budget.charge(1)?;
            for (slot, target) in targets.iter().enumerate() {
                budget.charge(1)?;
                incoming[*target].push((slot, colours[source]));
            }
        }
        let mut classes = BTreeMap::new();
        let mut refined = Vec::new();
        for i in 0..colours.len() {
            let size = incoming[i].len();
            budget.charge(
                1 + fields[i].len()
                    + size.saturating_mul(usize::BITS as usize - size.leading_zeros() as usize),
            )?;
            incoming[i].sort_unstable();
            let signature = (
                colours[i],
                fields[i].iter().map(|j| colours[*j]).collect::<Vec<_>>(),
                std::mem::take(&mut incoming[i]),
            );
            let next = classes.len();
            refined.push(*classes.entry(signature).or_insert(next));
        }
        let mut balance = vec![0isize; classes.len()];
        for (i, c) in refined.iter().enumerate() {
            budget.charge(1)?;
            balance[*c] += if i < n { 1 } else { -1 };
        }
        if balance.iter().any(|v| *v != 0) {
            return Ok(None);
        }
        // Refinement cannot merge existing classes because their old colour is
        // part of every signature. An unchanged class count is a fixed partition.
        let old_count = colours.iter().copied().max().map_or(0, |c| c + 1);
        if classes.len() == old_count {
            return Ok(Some(refined));
        }
        colours = refined;
    }
}

/// Observe a validated whole graph without imposing configuration validity on
/// the resulting projection.
pub fn all(
    graph: &Graph,
    limits: graph_core::GraphLimits,
    observation: ObservationLimits,
) -> Result<Observation> {
    Observer::all().project(&ValidatedGraph::new(graph, &limits)?, observation)
}

